[data-workspace-area="conversation"],.messages-timeline-scroll,[data-chat-header]{background:transparent!important}
[data-chat-header]{backdrop-filter:blur(8px);border-bottom:1px solid rgba(43,255,136,.12)!important}
[data-slot="composer-host"]{--chat-composer-outline:rgba(43,255,136,.3)!important;background:rgba(4,14,9,.72)!important;backdrop-filter:blur(14px) saturate(140%);box-shadow:0 10px 40px rgba(0,0,0,.5);animation:mxGlow 4s ease-in-out infinite}
[data-slot="composer-host"]:focus-within{--chat-composer-outline:rgba(43,255,136,.6)!important}
@keyframes mxGlow{50%{box-shadow:0 0 24px rgba(43,255,136,.16),0 10px 40px rgba(0,0,0,.5)}}
.composer-tiptap{caret-color:#2bff88}
[data-user-message-bubble]{background:rgba(10,40,24,.7)!important;border:1px solid rgba(43,255,136,.28)!important;backdrop-filter:blur(10px);color:#d9ffe9!important}
[data-message-role="assistant"] .chat-markdown{text-shadow:0 0 18px rgba(2,7,5,.9)}
.chat-markdown h1,.chat-markdown h2,.chat-markdown h3{color:#7dffb5!important;text-shadow:0 0 12px rgba(43,255,136,.45);letter-spacing:.01em}
.chat-markdown a{color:#2bff88!important}
.chat-markdown :not(pre)>code{color:#7dffb5!important}
.chat-markdown-codeblock{border:1px solid rgba(43,255,136,.25)!important;box-shadow:inset 0 0 30px rgba(43,255,136,.05)}
[data-slot="sidebar-inner"]{background:linear-gradient(180deg,#04100a,#020705)!important;border-right:1px solid rgba(43,255,136,.12)!important}
[data-thread-item]{transition:box-shadow .2s}
[data-thread-item]:hover{box-shadow:inset 2px 0 0 #2bff88}
[data-slot="tooltip-popup"]{background:#06170e!important;color:#7dffb5!important;border:1px solid rgba(43,255,136,.35)}
[data-slot="dialog-popup"],[data-slot="popover-popup"],[data-slot="menu-popup"]{border:1px solid rgba(43,255,136,.25)!important;box-shadow:0 0 40px rgba(43,255,136,.08),0 20px 50px rgba(0,0,0,.6)!important}
::selection{background:rgba(43,255,136,.3);color:#fff}
::-webkit-scrollbar{width:9px}::-webkit-scrollbar-thumb{background:rgba(43,255,136,.28);border-right:3px solid transparent;background-clip:padding-box;border-radius:9px}
@media (prefers-reduced-motion:reduce){[data-slot="composer-host"]{animation:none}}
